contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // We take params: amount to withdraw, claim flag, recipient, and a callerType flag to choose operator vs owner.
    function run(uint256 amount, bool claim, address to, uint8 callerType) public payable {
        require(callerType <= 2, "bad callerType");

        // Read observable before-values
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // Decide who will call: operator (0) or owner (1) or neither (2)
        // We need to perform calls as this contract (the checker deploys c and then runs run with this contract as msg.sender).
        // To simulate operator vs owner, we call c.setOperator or transferOwnership if we are the owner.
        // But only owner can call setOperator/transferOwnership. The constructor of C set owner to this contract when deployed by checker,
        // so here this contract is c.owner() and thus can set operator or transfer ownership.

        // Set operator to this contract if callerType==0, otherwise set operator to some other address when callerType==1
        if (callerType == 0) {
            // ensure operator is this contract so the subsequent withdraw call will be from operator
            c.setOperator(address(this));
        } else if (callerType == 1) {
            // ensure operator is not this contract (transfer to zero or another address)
            c.setOperator(address(0xdead));
            // also transfer ownership to this contract to allow owner-only path; this contract already is owner normally but safe to ensure
            // (transferOwnership requires non-zero address)
            c.transferOwnership(address(this));
        } else {
            // Neither operator nor owner: set operator to some other account and transfer ownership away
            c.setOperator(address(0xdead));
            c.transferOwnership(address(0xfeed));
        }

        // Now attempt the withdrawAndUnwrap call and capture whether it reverted
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read observable after-values
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // If the call succeeded (did not revert) and a non-zero recipient was provided then the amount transferred out cannot exceed the requested amount,
        // and the contract's CLP balance must not have increased.
        // Formally: !reverted && to != address(0) => (beforeBalance >= afterBalance) && (beforeBalance - afterBalance <= amount)
        // For safety avoid underflow in assert by rearranging: afterBalance <= beforeBalance && (beforeBalance - afterBalance) <= amount

        assert(reverted || to == address(0) || (afterBalance <= beforeBalance && (beforeBalance - afterBalance) <= amount));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // params: amount to withdraw, claim flag, recipient, mode: 0=set operator to this (call as operator), 1=ensure owner is this (call as owner), 2=neither
    function run(uint256 amount, bool claim, address to, uint8 mode) public payable {
        require(mode <= 2, "bad mode");

        // Read before balance
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // Setup so that this contract is operator (mode==0) or owner (mode==1) or neither (mode==2).
        // All calls must be top-level statements.
        if (mode == 0) {
            c.setOperator(address(this));
        }
        if (mode == 1) {
            // transferOwnership requires onlyOwner, and this contract is the owner at deployment by the checker.
            c.transferOwnership(address(this));
        }
        if (mode == 2) {
            // Set operator to an address that is not this and transfer ownership away.
            c.setOperator(address(0xdead));
            c.transferOwnership(address(0xfeed));
        }

        // Attempt the action and capture revert flag. This is a top-level try call.
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Read after balance
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // The asserted general rule:
        // If the call did not revert AND the caller was operator or owner (mode 0 or 1) AND a non-zero recipient was provided,
        // then afterBalance <= beforeBalance and the decrease (beforeBalance - afterBalance) <= amount.
        // We express it so arithmetic in assert cannot underflow: afterBalance <= beforeBalance implies subtraction is safe.
        assert(
            reverted || to == address(0) || mode == 2 || (afterBalance <= beforeBalance && (beforeBalance - afterBalance) <= amount)
        );
    }

    receive() external payable {}
}

