contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry as required
    function run(address caller, uint256 amount, bool claim, address to) public payable {
        require(caller != address(0)); // ensure a sensible 'operator/owner' candidate

        // read observable before-state
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // try calling withdrawAndUnwrap as either operator/owner or as other; capture revert
        bool reverted;
        // we must invoke c.withdrawAndUnwrap from this contract (msg.sender will be this test contract)
        // The rule will be about the effect when the call does not revert.
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read observable after-state and other relevant getters
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // If the call did not revert, then the contract's clpToken balance cannot have increased as a result
        // and if tokens were sent to a nonzero recipient, the amount sent cannot exceed the requested amount.
        // We don't have direct measurement of the exact transfer amount to `to`, but we can assert that
        // the contract's balance did not increase, and that if `to` is nonzero then the contract's balance
        // decreased by at most `amount` (i.e., before - after <= amount). This avoids underflow by using comparisons.

        assert(
            reverted
            || (
                // no increase in contract's clpToken balance
                afterBalance <= beforeBalance
                // and any decrease is at most the requested amount
                && (beforeBalance - afterBalance <= amount)
                // and if recipient is zero address, the function may choose not to transfer; allow that
            )
        );
    }

    receive() external payable {}
}

