contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    function run(bool claimExtras) public payable {
        // Observe pre-call clpToken balance of contract C and reward tokens balances of this test contract
        uint256 beforeClp = c.clpToken().balanceOf(address(c));

        address[] memory rewards = new address[](c.rewardTokens().length);
        // read rewardTokens array length and elements via public getter: rewardTokens is public so rewardTokens(uint) exists
        uint256 rtLen = c.rewardTokens().length;
        for (uint256 i = 0; i < rtLen; ) {
            rewards[i] = c.rewardTokens(i);
            unchecked { ++i; }
        }

        uint256[] memory beforeBalances = new uint256[](rtLen);
        for (uint256 i = 0; i < rtLen; ) {
            beforeBalances[i] = IERC20(rewards[i]).balanceOf(address(this));
            unchecked { ++i; }
        }

        // Call the state-changing function at top-level and capture whether it reverted
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call clpToken balance and reward token balances
        uint256 afterClp = c.clpToken().balanceOf(address(c));

        uint256[] memory afterBalances = new uint256[](rtLen);
        for (uint256 i = 0; i < rtLen; ) {
            afterBalances[i] = IERC20(rewards[i]).balanceOf(address(this));
            unchecked { ++i; }
        }

        // General rule:
        // If call reverted then nothing is required here. If it succeeded then:
        // 1) clpToken balance of C did not increase
        // 2) For each reward token, the increase in this contract's balance is at most the decrease in C's balance for that token (since transfers from C to rewardsRecipient or others cannot magically create tokens)
        // Note: we can only observe balances of C for clpToken; for reward tokens we only observe this contract's balance, so we assert that this contract's balance did not increase by more than could be plausibly transferred (nonnegative and bounded by observed changes in this contract's own balance). This is a conservative invariant: increases must be nonnegative and not arbitrarily large.

        // Build condition for reward balances: each after >= before and (after - before) is finite (always true), so we assert non-negativity of increase and clp non-increase.
        bool cond = reverted || (afterClp <= beforeClp);

        // Also require that for every reward token, this contract's balance did not decrease (since getReward should only transfer out of C to rewardsRecipient, not from this test contract)
        for (uint256 i = 0; i < rtLen; ) {
            cond = cond && (afterBalances[i] >= beforeBalances[i]);
            unchecked { ++i; }
        }

        assert(cond);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entry performing the property check
    function run(bool claimExtras) public payable {
        // Observe pre-call clpToken balance of contract C
        uint256 beforeClp = c.clpToken().balanceOf(address(c));

        // Read rewardTokens length via the public getter pattern: rewardTokens(uint256) exists; iterate until a revert to determine length
        // However the contract also has public array rewardTokens, but no length getter; we can probe indices until a call reverts.
        // To avoid indefinite loops, cap at 16 tokens which is reasonable for tests; this still uses only public surface.
        uint256 cap = 16;
        uint256 rtLen = 0;
        address[] memory rewards = new address[](cap);
        for (uint256 i = 0; i < cap; i++) {
            // try to read c.rewardTokens(i)
            try c.rewardTokens(i) returns (address addr) {
                rewards[i] = addr;
                rtLen = i + 1;
            } catch {
                break;
            }
        }

        // Record this test contract's balances for each discovered reward token
        uint256[] memory beforeBalances = new uint256[](rtLen);
        for (uint256 i = 0; i < rtLen; i++) {
            beforeBalances[i] = IERC20(rewards[i]).balanceOf(address(this));
        }

        // Call the state-changing function at top-level and capture whether it reverted
        bool reverted;
        try c.getReward(claimExtras) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe post-call clpToken balance and reward token balances
        uint256 afterClp = c.clpToken().balanceOf(address(c));

        uint256[] memory afterBalances = new uint256[](rtLen);
        for (uint256 i = 0; i < rtLen; i++) {
            afterBalances[i] = IERC20(rewards[i]).balanceOf(address(this));
        }

        // General rule (single assert): either the call reverted, or
        // 1) C's clpToken balance did not increase (afterClp <= beforeClp)
        // 2) For every known reward token, this test contract's balance did not decrease (afterBalances[i] >= beforeBalances[i])
        bool ok = reverted || (afterClp <= beforeClp);
        for (uint256 i = 0; i < rtLen; i++) {
            ok = ok && (afterBalances[i] >= beforeBalances[i]);
        }

        assert(ok);
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = msg.sender; }

    // single public entry point as required
    // params: caller (as address), amount, claim flag, recipient 'to'
    // We model two caller-categories by using a boolean isOperator to decide whether
    // this contract will first set operator to itself (allowed only by owner). The test
    // then attempts withdrawAndUnwrap from the chosen caller (this test contract uses msg.sender
    // when calling c, so we simulate caller by whether this contract is operator or not).
    function run(bool makeThisOperator, uint256 amount, bool claim, address to) public payable {
        require(to != address(0) || to == address(0), true);

        // read initial values
        address initialOperator = c.operator();
        address initialOwner = c.owner();

        // If makeThisOperator is true, attempt to set this contract as operator by calling setOperator.
        // Only the owner can call setOperator. The InvMutTest contract is NOT the original owner in general.
        // To allow changing operator, if the test contract is the owner, it will succeed; otherwise the call will revert.
        bool setOpReverted;
        if (makeThisOperator) {
            // try to call setOperator; capture revert
            try c.setOperator(address(this)) {
                setOpReverted = false;
            } catch {
                setOpReverted = true;
            }
        } else {
            setOpReverted = true; // we didn't try to become operator
        }

        // Now attempt withdrawAndUnwrap from this contract (it will be msg.sender for calls here).
        bool withdrawReverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observations after the call
        uint256 clpBalance = c.clpToken().balanceOf(address(c));
        // Whether this contract is recognized as operator now
        bool isNowOperator = (c.operator() == address(this));
        // Whether this contract is owner
        bool isOwner = (c.owner() == address(this));

        // General rule (assert): If this contract is neither operator nor owner (i.e., both false),
        // then withdrawAndUnwrap MUST revert. If this contract is operator or owner, withdrawAndUnwrap MUST NOT revert.
        // We allow that our earlier attempt to set operator may have or have not reverted; final state determines allowed caller.
        assert(((!isNowOperator && !isOwner) && withdrawReverted) || ((isNowOperator || isOwner) && !withdrawReverted));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint
    function run(bool tryBecomeOperator, uint256 amount, bool claim, address to) public payable {
        // no preconditions on parameters

        // Record initial owner and operator
        address initialOwner = c.owner();
        address initialOperator = c.operator();

        // Attempt to set this contract as operator if requested. Capture whether it reverted.
        bool setOpReverted = true;
        if (tryBecomeOperator) {
            try c.setOperator(address(this)) {
                setOpReverted = false;
            } catch {
                setOpReverted = true;
            }
        }

        // Now attempt withdrawAndUnwrap as this contract (msg.sender == address(this) for calls)
        bool withdrawReverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observe final operator and owner
        bool isNowOperator = (c.operator() == address(this));
        bool isOwner = (c.owner() == address(this));

        // Assert the general rule: withdrawAndUnwrap succeeds exactly when caller is operator or owner
        assert(((isNowOperator || isOwner) && !withdrawReverted) || ((!isNowOperator && !isOwner) && withdrawReverted));
    }

    receive() external payable {}
}

