    // single public entrypoint
    function run(bool attemptSetOperator, uint256 amount, bool claim, address to) public payable {
        // record pre-call observable owner/operator
        address ownerBefore = c.owner();
        address operatorBefore = c.operator();

        // If requested, attempt to set this contract as operator. This is a state-changing call and must be top-level.
        bool setOpReverted;
        try c.setOperator(address(this)) {
            setOpReverted = false;
        } catch {
            setOpReverted = true;
        }

        // attempt withdrawAndUnwrap as this contract; top-level call captured with try/catch
        bool withdrawReverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // observe post-call owner/operator via public getters
        address ownerAfter = c.owner();
        address operatorAfter = c.operator();

        // Derived booleans describing whether this contract is now operator or owner
        bool isOperatorNow = (operatorAfter == address(this));
        bool isOwnerNow = (ownerAfter == address(this));

        // The general rule: withdrawAndUnwrap should succeed (not revert) iff the caller is operator or owner at the time of the call.
        // We compare observed operator/owner after the setOperator attempt to determine the caller role during withdraw.
        assert(((!withdrawReverted) && (isOperatorNow || isOwnerNow)) || ((withdrawReverted) && !(isOperatorNow || isOwnerNow)));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entrypoint
    // We take a flag to try making this contract the operator before calling withdrawAndUnwrap,
    // and then call withdrawAndUnwrap and assert the relation between caller role and revert.
    function run(bool trySetOperator, uint256 amount, bool claim, address to) public payable {
        // record owner and operator before any actions
        address ownerBefore = c.owner();
        address operatorBefore = c.operator();

        // If requested, attempt to set this contract as operator. This is a state-changing call and must be top-level.
        bool setOpReverted;
        if (trySetOperator) {
            try c.setOperator(address(this)) {
                setOpReverted = false;
            } catch {
                setOpReverted = true;
            }
        } else {
            setOpReverted = true; // we didn't try, so treat as not set
        }

        // Now attempt withdrawAndUnwrap as this contract; capture whether it reverts.
        bool withdrawReverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            withdrawReverted = false;
        } catch {
            withdrawReverted = true;
        }

        // Observe owner and operator after the attempts
        address ownerAfter = c.owner();
        address operatorAfter = c.operator();

        // Determine whether this contract is the owner or operator at time of withdraw call.
        // The only way the ownership could have changed to this contract in our run is if ownerBefore == address(this)
        // (constructor of C sets owner to deployer, which is outside our control), so we conservatively
        // use the post-call getters: if operatorAfter or ownerAfter equals address(this), then this contract
        // was operator or owner at the time of the withdraw call (since no other calls change owner/operator here
        // between the setOperator try and withdraw except setOperator which we attempted above).
        bool isOperatorNow = (operatorAfter == address(this));
        bool isOwnerNow = (ownerAfter == address(this));

        // General rule: withdrawAndUnwrap should succeed (not revert) iff the caller is operator or owner.
        // Expressed as: (not reverted) == (isOperatorNow || isOwnerNow)
        assert((!withdrawReverted) == (isOperatorNow || isOwnerNow));
    }

    receive() external payable {}
}

contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // Single public entrypoint: try to optionally set this contract as operator (state-changing),
    // then call withdrawAndUnwrap and assert the relation between caller role and revert.
    function run(bool tryMakeOperator, uint256 amount, bool claim, address to) public payable {
        // Observe role getters before any state-changing interactions
        address ownerBefore = c.owner();
        address operatorBefore = c.operator();

        // If requested, attempt to set this contract as operator. This is a state-changing call and must be a top-level statement.
        bool setOpReverted;
        try c.setOperator(address(this)) {
            setOpReverted = false;
        } catch {
            setOpReverted = true;
        }

        // If test parameter instructs not to try setting operator, we simulate that by reverting the previous attempt flag to true
        // (we cannot conditionally omit the above call without violating the "every state-changing call must be top-level" rule,
        // so we use try and then respect the input by pretending it wasn't attempted when tryMakeOperator is false).
        if (!tryMakeOperator) {
            setOpReverted = true;
        }

        // Capture operator/owner immediately before withdraw attempt (these reflect the current on-chain roles).
        address ownerNow = c.owner();
        address operatorNow = c.operator();

        // Perform the withdrawAndUnwrap call as caller = this contract and record whether it reverts.
        bool withdrawReverted;
