    // We take an index and simulate two scenarios by setting rewardsRecipient via owner-only function.
    // Since this test contract is the deployer/owner of c in the checker setup, we can call owner-only functions.
    // The test verifies that if rewardsRecipient is non-zero then after getReward the balances of each reward token
    // are either zero (transferred away) or unchanged if recipient is zero; formally: when recipient != address(0),
    // every reward token's balance held by c after getReward is <= its balance before; when recipient == address(0),
    // balances are unchanged. Also ensure getReward does not revert just because some token balance is zero.

    function run(uint256 tokenCount, address recipient) public payable {
        require(tokenCount <= 20, "too many tokens");
        // set recipient (onlyOwner): owner is this contract per harness assumptions
        c.setRewardsRecipient(recipient);

        // read balances before for each reward token index up to tokenCount
        uint256[] memory before = new uint256[](tokenCount);
        for (uint256 i = 0; i < tokenCount; ++i) {
            address tok = c.rewardTokens(i);
            before[i] = IERC20(tok).balanceOf(address(c));
        }

        bool reverted;
        try c.getReward(true) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // read balances after
        uint256[] memory after = new uint256[](tokenCount);
        for (uint256 i = 0; i < tokenCount; ++i) {
