        // We cannot know external tokens' behavior, but we assert a general relation:
        // If recipient is non-zero and call did not revert, then for every token after <= before.
        // If recipient is zero and call did not revert, balances must be equal (no transfers made).
        // If it reverted, we cannot assert balances; include that in condition.
        bool ok = true;
        if (!reverted) {
            if (recipient != address(0)) {
                for (uint256 i = 0; i < tokenCount; ++i) {
                    if (!(after[i] <= before[i])) { ok = false; break; }
                }
            } else {
                for (uint256 i = 0; i < tokenCount; ++i) {
