contract InvMutTest {
    C c;

    constructor(C _c) { c = _c; }

    // single public function with inputs: caller selector via using onlyOperator/onlyOperatorOrOwner semantics
    // We will simulate calls from operator/owner by invoking functions on c directly because msg.sender in checker is this contract.
    // The rule: when we call withdrawAndUnwrap(amount, claim, to) as this contract (which is neither owner nor operator by default), it must revert;
    // if we first set this contract as owner via transferOwnership, then calling withdrawAndUnwrap should NOT increase clpToken.balanceOf(address(c)).

    function run(uint256 amount, bool claim, address to, address newOperator) public payable {
        require(to != address(0) || to == address(0), true); // no-op to use params

        // Record balance before
        uint256 before = c.clpToken().balanceOf(address(c));

        // Attempt call as non-operator/non-owner: should revert with NotOperatorOrOwner
        bool revertedNonAuthorized;
        try c.withdrawAndUnwrap(amount, claim, to) {
            revertedNonAuthorized = false;
        } catch {
            revertedNonAuthorized = true;
        }

        // Now set this contract as owner by transferring ownership to this contract
        // Only the current owner can call transferOwnership; the freshly deployed c's owner is the deployer (checker), not us.
        // However the test contract can call setOperator only if it is owner — so instead we attempt to call setOperator and recover whether it reverts.
        // We'll try to set operator to newOperator (no state observation required), ignoring success.
        bool setOpReverted;
        try c.setOperator(newOperator) {
            setOpReverted = false;
        } catch {
            setOpReverted = true;
        }

        // Now try withdrawAndUnwrap again; record balance after regardless of revert
        bool revertedAfter;
        try c.withdrawAndUnwrap(amount, claim, to) {
            revertedAfter = false;
        } catch {
            revertedAfter = true;
        }

        uint256 after = c.clpToken().balanceOf(address(c));

        // Assert general rule:
        // - The first call (as non-authorized) must revert OR the balance must not have increased.
        // - If the second call did not revert (meaning we acted as owner/operator), then the contract's clpToken balance must be <= before (i.e., cannot increase from a withdraw).
        // Combine into one assertion over observed flags and balances.
        assert(
            (
                revertedNonAuthorized || after <= before
            ) && (
                (!revertedAfter) ? after <= before : true
            )
        );
    }

    receive() external payable {}
}

