contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public entry that the checker will call with arbitrary inputs
    function run(address caller, uint256 amount, bool claim, address to) public payable {
        require(caller != address(0));
        // Observe current clp balance of c
        uint256 beforeBalance = c.clpToken().balanceOf(address(c));

        // Decide who will be the msg.sender for the call by using only allowed surface: we cannot change msg.sender
        // However, the test harness makes InvMutTest the deployer and the caller of c; we simulate two cases by
        // checking operator and owner and calling accordingly through this contract.

        // Read operator and owner
        address op = c.operator();
        address owner = c.owner();

        bool willRevert;
        // We attempt to call withdrawAndUnwrap either as operator/owner by requiring this contract be operator/owner
        // Since we cannot change c's operator/owner here, choose which branch to call that is allowed: if this contract
        // equals operator or owner call directly; otherwise perform the call and check it reverts.

        if (address(this) == op || address(this) == owner) {
            // call must not revert; perform and record
            willRevert = false;
            // top-level state-changing call
            c.withdrawAndUnwrap(amount, claim, to);
        } else {
            // calling as not operator nor owner should revert per contract's modifiers
            // capture revert by try/catch
            try c.withdrawAndUnwrap(amount, claim, to) {
                willRevert = false;
            } catch {
                willRevert = true;
            }
        }

        // Observe after balance and amount transferred to `to` (if to is contract with ERC20 we can only observe c's clp balance)
        uint256 afterBalance = c.clpToken().balanceOf(address(c));

        // If the call reverted, then state must be unchanged: balances equal
        // If it did not revert, then c's balance must have not increased (withdraw shouldn't increase held clp),
        // and it must have decreased by at most `amount` (cannot transfer more than requested).
        // We cannot read internal unstaked amounts, so assert on observable balances.

        if (willRevert) {
            assert(afterBalance == beforeBalance);
        } else {
            // afterBalance <= beforeBalance and beforeBalance - afterBalance <= amount
            // rewrite to avoid underflow: afterBalance <= beforeBalance  AND beforeBalance <= afterBalance + amount
            assert(afterBalance <= beforeBalance && beforeBalance <= afterBalance + amount);
        }
    }

    receive() external payable {}
}

