    C c;
    address deployer;
    constructor(C _c) { c = _c; deployer = address(this); }

    // single public entrypoint for property-based checking
    function run(address caller, address newOperator) public payable {
        require(caller != address(0));
        // record original operator and owner
        address origOperator = c.operator();
        address owner = c.owner();

        // Try to call setOperator as `caller`. Because the checker executes with this contract
        // as msg.sender for calls on c, we emulate calls from `caller` by requiring that
        // when caller == address(this) we actually invoke; otherwise we must NOT change state.
        // To test behavior for both cases, we perform two top-level calls: when caller == this, call setOperator;
        // and always attempt to call setOperator from this contract but only if this contract is owner.

        bool revertedWhenNotOwner;
        // First, if this contract is not the specified caller, we cannot actually change msg.sender dynamically.
        // So we model: if caller != address(this), then attempt must revert because sender isn't owner (unless owner == address(this)).
        // To observe behavior we try-catch a call that uses newOperator.
        if (caller != address(this)) {
            // attempt setOperator from this contract, expecting revert unless this contract is owner
            try c.setOperator(newOperator) {
                // succeeded
                revertedWhenNotOwner = false;
            } catch {
                revertedWhenNotOwner = true;
            }
        } else {
            // caller == address(this): perform actual call and record revert flag
            try c.setOperator(newOperator) {
                revertedWhenNotOwner = false;
            } catch {
                revertedWhenNotOwner = true;
            }
        }

        // Now determine what the rule should assert:
        // If this contract was the owner at call time, setOperator should succeed and operator() equals newOperator.
        // If this contract was not the owner, setOperator must revert (so operator unchanged) OR if it succeeded then owner==this (contradiction), so general rule:
        // After the attempted call, either the operator is newOperator and owner was address(this) at call-time, or operator remains origOperator and the call reverted or owner wasn't address(this).

        address finalOperator = c.operator();

        // Build the assertion: (finalOperator == newOperator) implies owner == address(this) and not revertedWhenNotOwner;
        // and (finalOperator == origOperator) implies (revertedWhenNotOwner || owner != address(this)).
        // Combine into a single boolean expression for the assert.
        bool ok1 = (finalOperator == newOperator) ? (!revertedWhenNotOwner && owner == address(this)) : true;
        bool ok2 = (finalOperator == origOperator) ? (revertedWhenNotOwner || owner != address(this)) : true;

        assert(ok1 && ok2);
    }

    receive() external payable {}
}

