contract InvMutTest {
    C c;
    constructor(C _c) { c = _c; }

    // single public test function taking parameters to drive behavior
    function run(address caller, uint256 amount, bool claim, address to) public payable {
        require(caller != address(0)); // caller will be used to set operator/owner via c's owner only functions not accessible here; just ensure nonzero

        // Observe clpToken balance before
        uint256 before = c.clpToken().balanceOf(address(c));

        // We will attempt to call withdrawAndUnwrap and catch whether it reverts.
        bool reverted;
        try c.withdrawAndUnwrap(amount, claim, to) {
            reverted = false;
        } catch {
            reverted = true;
        }

        // Observe after-balance
        uint256 after = c.clpToken().balanceOf(address(c));

        // If the call succeeded (did not revert), then the contract's clpToken balance must not have increased.
        // Also, if 'to' is non-zero and the call succeeded, at most 'amount' tokens could have been transferred out
        // so before - after <= amount (rearranged to avoid underflow in assert: after >= before - amount).
        // To express without subtraction underflow, we check: after <= before and (after >= before ? true : (before - after) <= amount).

        bool nonIncrease = (after <= before);
        bool transferredAtMostAmount;
        if (after >= before) {
            // no tokens left, so transferred amount is 0 <= amount
            transferredAtMostAmount = true;
        } else {
            // safe to compute before - after because after < before
            uint256 diff = before - after;
            transferredAtMostAmount = (diff <= amount);
        }

        assert(reverted || (nonIncrease && transferredAtMostAmount));
    }

    // allow receiving ETH if needed by c
    receive() external payable {}
}

